INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: hard / L4 — Controlled entity payments as UBIT (80%+ subsidiary excess over FMV)
(3, 'Tax-Exempt Organizations', 'Brightpath Foundation, a 501(c)(3) educational charity, owns 90% of a for-profit tutoring company. The tutoring company pays Brightpath $200,000 in annual rent for use of classroom space. An independent appraisal determines the fair market rental value is $120,000. Evaluate the UBIT treatment of this rental income under the controlled entity rules of Section 512(b)(13).', '["$80,000 is treated as UBIT because only the excess over fair market value from a controlled subsidiary is includable", "The entire $200,000 is excluded from UBIT because all rents from real property are exempt under Section 512(b)(3)", "The entire $200,000 is treated as UBIT because any payment from a controlled entity is fully taxable", "$120,000 is treated as UBIT because only the fair market value portion of controlled entity rent is taxable"]'::jsonb, 0, 'Under IRC Section 512(b)(13), rent paid by a controlled entity (80%+ ownership) to its tax-exempt parent is treated as UBIT to the extent it exceeds fair market value. Here, $200,000 minus $120,000 = $80,000 is includable. The general real property rent exclusion under Section 512(b)(3) does not apply to controlled entity payments that exceed FMV. Only the excess — not the entire amount or the FMV portion — is treated as unrelated business income.', 'hard', 4),

-- Q2: easy / L1 — Exempt purposes enumerated under Section 501(c)(3)
(3, 'Tax-Exempt Organizations', 'Which of the following is an exempt purpose under Section 501(c)(3)?', '["Generating profits for distribution to shareholders", "Fostering national or international amateur sports competition", "Operating a trade or business for the benefit of its owners", "Conducting political campaigns for candidates"]'::jsonb, 1, 'Under IRC Section 501(c)(3), fostering national or international amateur sports competition is one of the enumerated exempt purposes. Generating profits for shareholders violates the private inurement prohibition. Political campaign activity is absolutely prohibited under Section 501(c)(3). Operating a business for owners'' benefit fails the operational test.', 'easy', 1),

-- Q3: hard / L4 — Public charity one-third support test calculation under Section 509(a)(1)
(3, 'Tax-Exempt Organizations', 'Heritage Cultural Trust, a 501(c)(3) arts organization, receives the following support over a four-year period: $1,200,000 from a single family, $300,000 from government grants, and $100,000 from public contributions. Total support is $1,600,000. Evaluate whether Heritage qualifies as a public charity under the one-third support test of Section 509(a)(1) and the consequences of its classification.', '["Heritage qualifies as a public charity because government grants alone satisfy the one-third support requirement", "Heritage qualifies as a public charity because combined public and government support exceeds one-third", "Heritage is classified as a private foundation because public support of $400,000 is only 25% of total support, below the one-third threshold, subjecting it to excise taxes under Sections 4940 through 4945", "Heritage is classified as a private foundation solely because it receives more than 50% of support from a single donor"]'::jsonb, 2, 'Under IRC Section 509(a)(1), an organization must receive at least one-third of its total support from the general public or government to qualify as a public charity. Heritage''s qualifying public support is $400,000 ($300,000 government + $100,000 public), which is 25% of $1,600,000 — below the 33.33% threshold. Classification is based on the mathematical support test, not simply on having a single large donor. As a private foundation, Heritage faces excise taxes under Sections 4940 through 4945.', 'hard', 4),

-- Q4: medium / L3 — Convenience exclusion application for hospital cafeteria
(3, 'Tax-Exempt Organizations', 'Mercy General Hospital, a 501(c)(3), operates a cafeteria on its premises that serves meals to patients, staff, and visitors. The cafeteria is open during hospital hours, and 85% of sales are to patients, families, and employees. The remaining 15% are to walk-in members of the public. Apply the convenience exclusion under Section 513(a)(2) to determine the UBIT treatment.', '["The entire cafeteria income is subject to UBIT because the cafeteria sells to the general public", "Only the 15% from public walk-in sales is subject to UBIT while the 85% qualifies for the convenience exclusion", "The cafeteria income is subject to UBIT because food service is not substantially related to hospital exempt purposes", "The entire cafeteria income qualifies for the convenience exclusion because the cafeteria primarily serves patients, staff, and their families"]'::jsonb, 3, 'Under IRC Section 513(a)(2), a trade or business carried on for the convenience of members, students, patients, officers, or employees is excluded from UBIT. Because the hospital cafeteria primarily serves patients, families, and employees (85% of sales), the convenience exclusion applies to all income from the activity. The exclusion is evaluated based on the primary purpose of the activity, not on a per-customer allocation. Unlike the substantially related test, the convenience exclusion focuses on whom the facility principally serves.', 'medium', 3),

-- Q5: medium / L2 — Section 501(h) expenditure test election sliding scale
(3, 'Tax-Exempt Organizations', 'Hope Alliance, a 501(c)(3) public charity with $800,000 in exempt purpose expenditures, elects the Section 501(h) expenditure test to measure its lobbying activities. During the year, it spends $140,000 on direct lobbying and $25,000 on grassroots lobbying. Under the 501(h) election, what is Hope Alliance''s total lobbying nontaxable amount?', '["$145,000 — calculated as 20% of the first $500,000 plus 15% of the next $300,000", "A flat 5% of total exempt purpose expenditures, or $40,000", "No specific dollar limit — lobbying must simply not be a substantial part of activities", "25% of total exempt purpose expenditures, or $200,000"]'::jsonb, 0, 'Under IRC Section 501(h), the lobbying nontaxable amount is calculated on a sliding scale: 20% of the first $500,000 of exempt purpose expenditures plus 15% of the next $500,000. For $800,000: ($500,000 x 20%) + ($300,000 x 15%) = $100,000 + $45,000 = $145,000. This safe-harbor election replaces the subjective substantial part test with specific dollar thresholds. A flat percentage approach does not reflect the statutory sliding scale in Section 4911(c)(2).', 'medium', 2),

-- Q6: easy / L1 — Dissolution clause requirement under organizational test
(3, 'Tax-Exempt Organizations', 'What must a 501(c)(3) organization''s articles of incorporation include regarding asset distribution upon dissolution?', '["Assets must be distributed equally among the organization''s current members", "Assets must be returned to the original donors or their estates", "Assets may be distributed to any entity chosen by the board of directors", "Assets must be distributed to another exempt organization or to the government"]'::jsonb, 3, 'Under IRC Section 501(c)(3), the organizational test requires that governing documents include a dissolution clause providing that upon dissolution, remaining assets will be distributed to another tax-exempt organization or to the government. This prevents private benefit upon dissolution. Distribution to members (choice A) or unrestricted board discretion (choice C) would violate the organizational test requirement.', 'easy', 1),

-- Q7: easy / L1 — Form 990-PF required for all private foundations
(3, 'Tax-Exempt Organizations', 'What annual return must all private foundations file regardless of their size?', '["Form 990-N (e-Postcard)", "Form 990-PF", "Form 990-EZ", "Form 990"]'::jsonb, 1, 'Under IRC Section 6033, all private foundations must file Form 990-PF annually regardless of gross receipts or total assets. Unlike public charities, which may file Form 990-N or 990-EZ based on size thresholds, private foundations have no size-based filing exception. Form 990-PF includes detailed reporting on excise tax computations, grants, and investments specific to private foundations.', 'easy', 1),

-- Q8: medium / L3 — Personal property rents incidental rule (less than 10%)
(3, 'Tax-Exempt Organizations', 'Green Valley Foundation, a 501(c)(3), leases a building to a commercial tenant for $100,000 per year. The lease also includes office furniture and equipment for which the tenant pays an additional $8,000 annually. Apply the personal property rules under Section 512(b)(3) to determine the UBIT treatment of the rental income.', '["The entire $108,000 is subject to UBIT because the lease includes personal property", "The $100,000 real property rent is excluded but the $8,000 personal property rent is subject to UBIT", "The entire $108,000 is excluded from UBIT because the personal property rent of $8,000 is less than 10% of total rents, making it incidental", "Only the $8,000 personal property rent is excluded because personal property rents are always classified as passive income"]'::jsonb, 2, 'Under IRC Section 512(b)(3), rents from real property are excluded from UBIT, but rents from personal property are generally included. However, when personal property is leased with real property, the personal property rent is treated as excluded if it represents less than 10% of total rent under the lease. Here, $8,000 / $108,000 = 7.4%, which is below 10%. Therefore, the entire $108,000 is excluded. If the personal property portion were 10% or more, all personal property rent would be includable in UBIT.', 'medium', 3),

-- Q9: medium / L3 — NOL carryforward for UBIT computed from UBI items only
(3, 'Tax-Exempt Organizations', 'Riverside Education Fund, a 501(c)(3), has $150,000 of unrelated business income and $180,000 of directly connected expenses in Year 1, producing a net operating loss. In Year 2, it has $200,000 of unrelated business income and $120,000 of directly connected expenses. Apply the NOL rules under Section 512(b)(6) to determine Year 2 unrelated business taxable income.', '["$49,000 — the $30,000 Year 1 NOL carries forward, reducing $80,000 net UBI to $50,000, then the $1,000 specific deduction applies", "$80,000 — NOL carryforwards are not permitted for unrelated business income", "$79,000 — the $1,000 specific deduction applies to the $80,000 net UBI but no NOL carryforward is available", "$50,000 — the $30,000 NOL reduces $80,000 to $50,000 but no specific deduction applies"]'::jsonb, 0, 'Under IRC Section 512(b)(6), a net operating loss from unrelated business activities may be carried forward and deducted against future UBI, computed using only UBI items. Year 1 NOL: $180,000 - $150,000 = $30,000. Year 2 net UBI: $200,000 - $120,000 = $80,000. After the $30,000 NOL carryforward ($50,000) and the $1,000 specific deduction under Section 512(b)(12), taxable UBI is $49,000. NOL carryforwards are permitted (choice B is incorrect) and applied before the specific deduction.', 'medium', 3),

-- Q10: easy / L1 — Form 990 filing deadline for calendar-year organizations
(3, 'Tax-Exempt Organizations', 'What is the filing deadline for Form 990 for a calendar-year tax-exempt organization?', '["April 15", "May 15", "March 15", "June 15"]'::jsonb, 1, 'Under IRC Section 6033, Form 990 is due on the 15th day of the 5th month after the end of the organization''s tax year. For calendar-year organizations, this is May 15. This differs from the April 15 individual tax return deadline and the March 15 partnership return deadline. Extensions of up to six months are available using Form 8868.', 'easy', 1),

-- Q11: easy / L2 — Form 990-N (e-Postcard) gross receipts threshold
(3, 'Tax-Exempt Organizations', 'A small 501(c)(3) charity has gross receipts of $42,000 and total assets of $200,000 for the current year. Which annual information return must this organization file with the IRS?', '["Form 990 because total assets exceed $200,000", "Form 990-EZ because gross receipts are below $200,000", "Form 990-N (e-Postcard) because gross receipts are $50,000 or less", "No return is required for organizations with gross receipts below $50,000"]'::jsonb, 2, 'Under IRC Section 6033, organizations with gross receipts of $50,000 or less may file Form 990-N (e-Postcard), an electronic notice requiring only basic information such as name, address, and EIN. The 990-N threshold is based solely on gross receipts, not total assets. Form 990-EZ applies when gross receipts are under $200,000 AND total assets are under $500,000, but Form 990-N is the correct filing when receipts are $50,000 or less.', 'easy', 2),

-- Q12: medium / L2 — Research exclusion from UBIT for colleges and universities
(3, 'Tax-Exempt Organizations', 'State University, a 501(c)(3), operates a research laboratory that earns $500,000 from contracts with private pharmaceutical companies and $300,000 from a federal government research grant. How are these research revenues treated for UBIT purposes under Sections 512(b)(7) through (9)?', '["Both the private company contracts and the government grant are subject to UBIT", "Both are excluded only if the research results are made publicly available", "The government grant is excluded but the $500,000 private contracts are subject to UBIT", "All research income is excluded from UBIT because research by a college or university is exempt regardless of the funding source"]'::jsonb, 3, 'Under IRC Sections 512(b)(7) through (9), research income is excluded from UBIT when performed for the U.S. government, or when performed by a college, university, or hospital. For universities, the exclusion covers all research income regardless of the funding source, including private company contracts. This broad exclusion recognizes that research is fundamental to a university''s exempt educational purpose. Non-university exempt organizations would only exclude government-funded and publicly available research.', 'medium', 2),

-- Q13: medium / L3 — Section 4958 cumulative 25% initial + 200% additional tax
(3, 'Tax-Exempt Organizations', 'Vision Forward, a 501(c)(3), pays its program director Marcus Hall $650,000 when comparable positions pay $250,000. The IRS identifies the $400,000 excess benefit, but Hall does not return the excess amount within the correction period. Apply Section 4958 to determine the total excise taxes imposed on Hall.', '["$100,000 — the initial 25% tax on the $400,000 excess benefit", "$800,000 — the 200% additional tax alone, which replaces the initial tax", "$900,000 — the 25% initial tax of $100,000 plus the 200% additional tax of $800,000 for failure to correct", "$40,000 — a 10% intermediate sanction on the excess benefit"]'::jsonb, 2, 'Under IRC Section 4958, a disqualified person receiving an excess benefit must pay an initial tax of 25% ($400,000 x 25% = $100,000). If the excess is not corrected within the taxable period, an additional 200% tax applies ($400,000 x 200% = $800,000). Both taxes are cumulative, totaling $900,000. The 10% tax (choice D) applies to organization managers who knowingly participate, not to the disqualified person receiving the benefit.', 'medium', 3),

-- Q14: medium / L2 — Bingo games exclusion from UBIT under Section 513(f)
(3, 'Tax-Exempt Organizations', 'Lakeside Veterans Club, a 501(c)(3), hosts weekly bingo nights generating $75,000 annually. The bingo games are legal under state law, and no commercial bingo operations exist in the jurisdiction. Volunteers manage the events. How is the bingo income treated for UBIT purposes?', '["Excluded from UBIT because the bingo games are legal and commercial bingo is not ordinarily carried out in the jurisdiction", "Subject to UBIT because weekly bingo is a regularly carried on trade or business", "Excluded from UBIT solely because volunteers run the events", "Subject to UBIT because bingo is not related to the organization''s charitable purpose"]'::jsonb, 0, 'Under IRC Section 513(f), bingo games are specifically excluded from UBIT if the game is legal under state and local law and commercial bingo is not ordinarily carried out in the jurisdiction. This exclusion applies regardless of whether the activity meets the three-part UBIT test. While the volunteer exclusion under Section 513(a)(1) could independently apply, the bingo-specific exclusion under Section 513(f) is the primary statutory authority. The exclusion would not apply if commercial bingo operations existed in the same jurisdiction.', 'medium', 2),

-- Q15: hard / L3 — Section 4945 taxable expenditure for grant to non-501(c)(3) without expenditure responsibility
(3, 'Tax-Exempt Organizations', 'Morrison Family Foundation, a private foundation, awards a $200,000 grant to a 501(c)(4) social welfare organization for community health programs. The foundation does not exercise expenditure responsibility over the grant and does not verify how the funds are spent. Apply Section 4945 to determine the tax consequences.', '["No excise tax applies because the grant funds legitimate community health programs", "A 20% initial excise tax of $40,000 on the foundation because a grant to a non-501(c)(3) without expenditure responsibility is a taxable expenditure", "A 10% initial excise tax of $20,000 under the self-dealing rules of Section 4941", "A 30% excise tax of $60,000 under the failure-to-distribute rules of Section 4942"]'::jsonb, 1, 'Under IRC Section 4945(d)(4), a grant by a private foundation to a non-501(c)(3) organization is a taxable expenditure unless the foundation exercises expenditure responsibility, verifying that funds are used for charitable purposes. The initial excise tax is 20% of the expenditure ($200,000 x 20% = $40,000). This rule ensures private foundations cannot redirect funds to organizations outside IRS oversight without accountability. The 10% rate applies to self-dealing (Section 4941), and 30% applies to failure to distribute (Section 4942).', 'hard', 3),

-- Q16: hard / L4 — Supporting organization classification under Section 509(a)(3)
(3, 'Tax-Exempt Organizations', 'Scholars Aid Inc. is organized exclusively to raise funds for State University, a public charity. Its board includes three independent members and two university appointees, and it transfers 85% of annual revenue to the university for scholarships. Evaluate whether Scholars Aid qualifies as a public charity under Section 509(a)(3) and the significance of the supporting organization rules.', '["Scholars Aid is a private foundation because it does not independently meet the one-third public support test under Section 509(a)(1)", "Scholars Aid is a public charity under Section 509(a)(2) because of its gross receipts from fundraising activities", "Scholars Aid is a private foundation because supporting organizations must be wholly controlled by the supported charity", "Scholars Aid is a public charity under Section 509(a)(3) because it is organized and operated exclusively to support a public charity, regardless of whether it independently meets the public support tests"]'::jsonb, 3, 'Under IRC Section 509(a)(3), an organization qualifies as a public charity if it is organized and operated exclusively to support one or more public charities. The supporting organization need not independently meet the one-third support test of Section 509(a)(1). Scholars Aid meets this test by being organized exclusively to benefit State University and transferring the majority of its revenue accordingly. Full control by the supported charity is not required — the statute allows various organizational relationships including independent boards.', 'hard', 4),

-- Q17: medium / L2 — Churches automatically classified as public charities regardless of funding
(3, 'Tax-Exempt Organizations', 'Grace Community Church, a 501(c)(3) religious organization, receives 95% of its financial support from a single wealthy family. The church has never applied for a public charity determination. How is Grace Community Church classified for federal tax purposes?', '["As a private foundation because 95% of support comes from a single family", "As a private foundation because it has not applied for public charity determination", "As a public charity because churches are automatically classified as public charities regardless of their funding sources", "As a public charity only if it can demonstrate broad community support"]'::jsonb, 2, 'Under IRC Section 509(a)(1) and Section 170(b)(1)(A)(i), churches are automatically classified as public charities regardless of their funding sources. Unlike other 501(c)(3) organizations, churches do not need to meet the one-third public support test or apply for a specific determination. This same automatic classification applies to schools and hospitals. The concentration of funding from a single family does not override the statutory automatic classification for churches.', 'medium', 2),

-- Q18: hard / L4 — Section 4941 dual excise taxes on self-dealer and foundation manager
(3, 'Tax-Exempt Organizations', 'The Davis Charitable Foundation, a private foundation, leases office space from its founder''s wholly-owned corporation at $5,000 per month for 12 months ($60,000 total). The executive director, who is also a board member, approves the lease knowing the founder''s relationship. The board terminates the lease after six months. Evaluate the excise tax consequences for both the founder and the executive director under Section 4941.', '["The founder owes $6,000 (10% of $60,000) and no tax is imposed on the executive director because the lease was terminated", "Only the founder owes a 10% tax because the executive director acted in good faith by terminating the lease early", "No excise tax applies because the lease was terminated within the taxable period", "The founder owes $6,000 (10% of $60,000) as the self-dealer, and the executive director owes $3,000 (5% of $60,000) as a foundation manager who knowingly approved the transaction"]'::jsonb, 3, 'Under IRC Section 4941, any lease between a private foundation and a disqualified person constitutes self-dealing regardless of terms. The initial tax is 10% of the amount involved on the self-dealer ($60,000 x 10% = $6,000). A foundation manager who knowingly participates faces a 5% tax ($60,000 x 5% = $3,000), capped at $20,000 per act. Terminating the lease corrects self-dealing prospectively but does not eliminate taxes on amounts already paid. The executive director cannot claim good faith when knowingly approving a disqualified person transaction.', 'hard', 4),

-- Q19: hard / L4 — Debt-financed income ratio calculation under Section 514
(3, 'Tax-Exempt Organizations', 'Horizon Arts Council, a 501(c)(3), purchases a commercial building for $1,000,000 using $600,000 in borrowed funds. The property generates $120,000 in annual rental income. The average acquisition indebtedness during the year is $550,000 and the average adjusted basis is $900,000. Calculate the portion of rental income subject to UBIT under Section 514.', '["$73,333 — the rental income multiplied by the debt-to-basis ratio of $550,000 divided by $900,000", "The entire $120,000 because all rental income from debt-financed property is fully subject to UBIT", "$72,000 — the rental income multiplied by the original loan-to-value ratio of $600,000 divided by $1,000,000", "$82,500 — the rental income multiplied by $550,000 divided by the year-end adjusted basis"]'::jsonb, 0, 'Under IRC Section 514, debt-financed income is subject to UBIT in proportion to average acquisition indebtedness divided by average adjusted basis. The ratio is $550,000 / $900,000 = 61.1%, applied to $120,000 rental income = approximately $73,333. Section 514 specifically requires average adjusted basis, not the original purchase price (choice C uses loan-to-value) or year-end basis (choice D). Only the debt-financed portion is includable — not the entire rental amount.', 'hard', 4),

-- Q20: easy / L1 — Late filing penalty rate for Form 990
(3, 'Tax-Exempt Organizations', 'What is the daily penalty for a small tax-exempt organization that fails to file Form 990 on time?', '["$50 per day", "$20 per day", "$100 per day", "$10 per day"]'::jsonb, 1, 'Under IRC Section 6652(c)(1)(A), the penalty for failure to timely file Form 990 is $20 per day for each day the return is late, up to the lesser of $10,500 or 5% of the organization''s gross receipts for organizations with gross receipts under $1,186,000. For larger organizations, the penalty increases to $100 per day with a maximum of $53,000. The $20 daily rate is the standard penalty for smaller tax-exempt organizations.', 'easy', 1),

-- Q21: medium / L3 — Schedule J compensation disclosure on Form 990
(3, 'Tax-Exempt Organizations', 'Pacific Health Alliance, a 501(c)(3) hospital, is preparing its Form 990 and must report detailed compensation for its CEO, CFO, and chief medical officer. The controller asks which Form 990 schedule requires disclosure of officer and director compensation. Identify the correct schedule.', '["Schedule A, which reports executive compensation to verify public charity status", "Schedule B, which lists all compensated officers alongside major contributors", "Schedule J, which requires itemized compensation disclosure for officers, directors, and key employees", "Schedule D, which reports compensation as part of supplemental financial statements"]'::jsonb, 2, 'Form 990 Schedule J specifically requires detailed compensation information for officers, directors, trustees, and key employees of tax-exempt organizations. Schedule A reports public charity status and public support data, not compensation. Schedule B lists contributors and is confidential — it does not include compensation. Schedule D provides supplemental financial statements but does not serve as the primary compensation disclosure schedule.', 'medium', 3),

-- Q22: medium / L2 — Private inurement prohibition applied to insider below-market loan
(3, 'Tax-Exempt Organizations', 'Clearwater Community Foundation, a 501(c)(3), provides its board president with a below-market-rate loan of $500,000 at 1% interest when market rates are 6%. The board president exercises substantial influence over the organization. Which prohibition is most directly violated by this arrangement?', '["The private benefit doctrine, which applies only to transactions with non-insiders", "The private inurement prohibition, which prevents any part of net earnings from inuring to the benefit of insiders", "The excess business holdings rule under Section 4943", "The jeopardizing investments rule under Section 4944"]'::jsonb, 1, 'Under IRC Section 501(c)(3), the private inurement prohibition prevents net earnings of a tax-exempt organization from benefiting private shareholders or individuals — specifically insiders with control or influence. A below-market loan to a board president is a classic example of inurement because the insider receives an economic benefit at the organization''s expense. Private benefit (choice A) is broader and can apply to non-insiders. Sections 4943 and 4944 apply only to private foundations, not to this type of insider transaction.', 'medium', 2),

-- Q23: medium / L2 — Form 990-T filing threshold of $1,000 gross UBI
(3, 'Tax-Exempt Organizations', 'Sunshine Animal Rescue, a 501(c)(3), earns $850 of gross unrelated business income from selling advertising space in its monthly newsletter. The accountant asks whether Sunshine must file Form 990-T. What is the applicable filing threshold?', '["$500 or more of gross unrelated business income", "$100 or more of gross unrelated business income", "Any amount of gross unrelated business income requires filing", "$1,000 or more of gross unrelated business income"]'::jsonb, 3, 'Under IRC Section 6012(a)(6), a tax-exempt organization must file Form 990-T when it has $1,000 or more of gross unrelated business income. Since Sunshine''s gross UBI is only $850, it falls below the $1,000 threshold and is not required to file. This threshold aligns with the $1,000 specific deduction under Section 512(b)(12), effectively meaning organizations with less than $1,000 of gross UBI owe no tax and need not file.', 'medium', 2),

-- Q24: medium / L2 — Section 4943 combined holdings with disqualified persons exceeding 20%
(3, 'Tax-Exempt Organizations', 'The Harris Foundation, a private foundation, owns 12% of the voting stock of DataCorp. The foundation''s substantial contributors and their family members collectively own 15% of DataCorp. Under Section 4943, what is the combined ownership and does it create excess business holdings?', '["Combined holdings of 27% exceed the 20% permitted limit, creating 7% excess business holdings subject to a 10% excise tax", "No excess holdings exist because the foundation itself owns only 12%, which is below the 20% limit", "Combined holdings of 27% exceed a 35% permitted limit, so no excess exists", "Only the foundation''s 12% is counted because disqualified persons'' holdings are excluded from the calculation"]'::jsonb, 0, 'Under IRC Section 4943, a private foundation and all disqualified persons together may not own more than 20% of the voting stock of a business enterprise. The Harris Foundation (12%) plus its disqualified persons (15%) hold a combined 27%, exceeding the 20% limit by 7%. This 7% excess is subject to a 10% initial excise tax. The calculation combines both the foundation''s and disqualified persons'' holdings — the foundation cannot consider its holdings in isolation (choice B is incorrect).', 'medium', 2),

-- Q25: easy / L1 — Purpose of IRS Form 8868
(3, 'Tax-Exempt Organizations', 'What is the purpose of IRS Form 8868 for tax-exempt organizations?', '["To apply for tax-exempt status under Section 501(c)(3)", "To request an automatic extension of time to file an exempt organization return", "To report unrelated business taxable income", "To report changes in the organization''s governing documents"]'::jsonb, 1, 'IRS Form 8868 is used by tax-exempt organizations to request an automatic extension of up to six months for filing their annual information return (Form 990, 990-EZ, 990-PF, or 990-T). Form 1023 or 1023-EZ is used to apply for exempt status (choice A). Form 990-T reports unrelated business income (choice C). No single form is dedicated to reporting governing document changes (choice D).', 'easy', 1),

-- Q26: medium / L3 — Section 4945 taxable expenditure for lobbying by private foundation
(3, 'Tax-Exempt Organizations', 'Stone Creek Foundation, a private foundation, spends $75,000 lobbying Congress to support legislation expanding educational tax credits. The tax advisor believes this is permissible because it advances the foundation''s educational mission. Apply Section 4945 to evaluate the tax consequences.', '["No excise tax applies because the lobbying directly relates to the foundation''s educational exempt purpose", "A 10% excise tax of $7,500 applies under the self-dealing provisions of Section 4941", "A 20% excise tax of $15,000 applies because lobbying by a private foundation is a taxable expenditure under Section 4945(d)(1) regardless of its connection to the exempt purpose", "A 30% excise tax of $22,500 applies under the failure-to-distribute rules of Section 4942"]'::jsonb, 2, 'Under IRC Section 4945(d)(1), any amount paid by a private foundation to influence legislation is a taxable expenditure, regardless of whether the lobbying relates to the foundation''s exempt purpose. The initial excise tax is 20% ($75,000 x 20% = $15,000). Unlike public charities, which may engage in limited lobbying, private foundations face a near-absolute prohibition enforced through excise taxes. The advisor''s belief that mission alignment provides protection is incorrect — Section 4945 makes no exception for purpose-related lobbying.', 'medium', 3),

-- Q27: easy / L1 — Operational test definition
(3, 'Tax-Exempt Organizations', 'What does the operational test require for a 501(c)(3) organization?', '["The organization must generate sufficient revenue to cover its operating expenses", "The organization must be operated primarily for one or more exempt purposes", "The organization must be operated by a board of at least five independent directors", "The organization must distribute all net income annually to beneficiaries"]'::jsonb, 1, 'Under IRC Section 501(c)(3), the operational test requires that an organization be operated primarily for one or more exempt purposes — religious, charitable, scientific, educational, or other qualifying purposes. This test examines actual activities, not organizational documents (which are evaluated under the organizational test). There is no minimum board size requirement (choice C) or mandatory annual distribution for public charities (choice D).', 'easy', 1),

-- Q28: medium / L2 — Schedule B confidential from public inspection
(3, 'Tax-Exempt Organizations', 'Metro Arts Foundation, a 501(c)(3) public charity, files Form 990 and its attached schedules with the IRS. A journalist requests a copy of the organization''s Form 990 under public disclosure rules. Which schedule is exempt from public inspection?', '["Schedule B (Schedule of Contributors), which contains donor names and contribution amounts", "Schedule J (Compensation Information), which is confidential to protect employee privacy", "Schedule A (Public Charity Status), which contains proprietary financial formulas", "Schedule D (Supplemental Financial Statements), which is filed under seal with the IRS"]'::jsonb, 0, 'Under IRC Section 6104(d)(3), Schedule B (Schedule of Contributors) is specifically exempt from public inspection for most public charities. Donor names and contribution amounts are confidential. All other Form 990 schedules — including Schedule A (public charity status), Schedule D (supplemental financials), and Schedule J (compensation) — are publicly available. This protection encourages charitable giving by preserving donor privacy.', 'medium', 2),

-- Q29: easy / L1 — Private foundation presumption under Section 509
(3, 'Tax-Exempt Organizations', 'Under Section 509, which 501(c)(3) organizations are presumed to be private foundations?', '["Only organizations that receive funding from a single donor", "Only organizations with assets exceeding $5,000,000", "All 501(c)(3) organizations unless they demonstrate they qualify as a public charity", "Only organizations that do not file Form 990"]'::jsonb, 2, 'Under IRC Section 509(a), every 501(c)(3) organization is presumed to be a private foundation unless it can demonstrate it qualifies as a public charity under one of the exceptions — such as the one-third public support test, the gross receipts test, or automatic classification as a church, school, or hospital. The presumption is not based on donor count (choice A), asset size (choice B), or filing status (choice D).', 'easy', 1),

-- Q30: medium / L3 — Private benefit doctrine applied to non-insider excessive payment
(3, 'Tax-Exempt Organizations', 'Greenleaf Environmental Trust, a 501(c)(3), awards a $300,000 consulting contract to a firm owned by a community member with no affiliation to the board, officers, or key employees. The fee significantly exceeds market rates. Counsel argues that since no insider benefits, the private inurement prohibition does not apply. Evaluate whether any prohibition is violated.', '["The private benefit doctrine is violated because the organization confers excessive economic benefit on a non-insider, which threatens exempt status even without insider involvement", "No prohibition is violated because private inurement only applies to insiders and the private benefit doctrine does not apply to arm''s-length transactions", "The self-dealing rules under Section 4941 are violated because any above-market transaction is self-dealing", "The private inurement prohibition is violated because all above-market transactions constitute inurement regardless of the recipient''s relationship"]'::jsonb, 0, 'Under IRC Section 501(c)(3), the private benefit doctrine is broader than the private inurement prohibition. While inurement applies only to insiders with control or influence, private benefit applies to any person — including unaffiliated third parties. An above-market consulting contract that excessively benefits a non-insider violates the private benefit doctrine and can jeopardize exempt status. Section 4941 self-dealing rules apply only to private foundations and their disqualified persons, not to public charities and unaffiliated vendors.', 'medium', 3)
;

COMMIT;
